PROGRAM motor_interlock
VAR_INPUT
  Start : BOOL;
  Stop : BOOL;
  EStop : BOOL;
END_VAR
VAR_OUTPUT
  Motor : BOOL;
END_VAR
Motor := ((Start OR Motor) AND NOT Stop) AND EStop;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpState : BOOL;
END_VAR
ValveOut := Level >= 90;
IF Level <= 10 THEN
    PumpState := TRUE;
ELSIF Level >= 90 THEN
    PumpState := FALSE;
END_IF;
PumpIn := PumpState AND (Level < 90);
END_PROGRAM

PROGRAM airlock
VAR_INPUT
  OpenA_Cmd : BOOL;
  OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
  DoorA : BOOL;
  DoorB : BOOL;
END_VAR
DoorA := OpenA_Cmd AND NOT DoorB;
DoorB := OpenB_Cmd AND NOT DoorA;
END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
  StartPB : BOOL;
  StopPB : BOOL;
  GuardClosed : BOOL;
  Fault : BOOL;
END_VAR
VAR_OUTPUT
  Conveyor : BOOL;
END_VAR
Conveyor := (StartPB AND GuardClosed AND NOT Fault) OR (Conveyor AND NOT StopPB AND GuardClosed AND NOT Fault);
END_PROGRAM

PROGRAM alarm_ctrl
VAR_INPUT
Trip : BOOL;
Reset : BOOL;
END_VAR
VAR_OUTPUT
Alarm : BOOL;
END_VAR
Alarm := Trip OR (Alarm AND NOT (Reset AND NOT Trip));
END_PROGRAM

PROGRAM heater_ctrl
VAR_INPUT
	HeatRequest : BOOL;
	Enable : BOOL;
	OverTemp : BOOL;
END_VAR
VAR_OUTPUT
	Heater : BOOL;
END_VAR
Heater := HeatRequest AND Enable AND NOT OverTemp;
END_PROGRAM

PROGRAM pump_ctrl
VAR_INPUT
    Demand : BOOL;
    LowLevel : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
END_VAR
Pump := Demand AND NOT LowLevel;
END_PROGRAM

PROGRAM intersection
VAR_OUTPUT
NS_G : BOOL;
NS_Y : BOOL;
NS_R : BOOL;
EW_G : BOOL;
EW_Y : BOOL;
EW_R : BOOL;
END_VAR
VAR
State : INT := 0;
GreenTimer : TON;
YellowTimer : TON;
AllRedTimer : TON;
END_VAR
VAR CONSTANT
PT_GREEN : TIME := T#2s;
PT_YELLOW : TIME := T#1s;
PT_ALLRED : TIME := T#1s;
END_VAR
GreenTimer(IN := (State=0) OR (State=3), PT := PT_GREEN);
YellowTimer(IN := (State=1) OR (State=4), PT := PT_YELLOW);
AllRedTimer(IN := (State=2) OR (State=5), PT := PT_ALLRED);
IF GreenTimer.Q AND (State=0 OR State=3) THEN
State := State + 1;
ELSIF YellowTimer.Q AND (State=1 OR State=4) THEN
State := State + 1;
ELSIF AllRedTimer.Q AND (State=2 OR State=5) THEN
IF State=5 THEN State:=0; ELSE State:=3; END_IF;
END_IF;
NS_G := State=0;
NS_Y := State=1;
NS_R := State>=2;
EW_G := State=3;
EW_Y := State=4;
EW_R := NOT (State=3 OR State=4);
END_PROGRAM

PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
MotorUp := FALSE;
MotorDown := FALSE;
IF DoorClosed THEN
    IF State = 1 AND NOT AtTop THEN
        MotorUp := TRUE;
    ELSIF State = 3 AND NOT AtBottom THEN
        MotorDown := TRUE;
    END_IF;
END_IF;
IF AtBottom THEN
    State := 0;
ELSIF AtTop THEN
    State := 2;
ELSIF State = 0 AND CallUp AND DoorClosed THEN
    State := 1;
ELSIF State = 2 AND CallDown AND DoorClosed THEN
    State := 3;
END_IF;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    ReactTimer : TON;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    TEMP_SET : INT := 100;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    REACT_TIME : TIME := T#3s;
END_VAR
IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    ReactTimer(IN := (State = 3), PT := REACT_TIME);
    CASE State OF
        0: (* Idle *)
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF StartBatch THEN State := 1; END_IF;
        1: (* Fill *)
            FillValve := (Level < LVL_HIGH);
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF Level >= LVL_HIGH THEN State := 2; END_IF;
        2: (* Heat *)
            FillValve := FALSE;
            Heater := (Level >= LIQ_MIN);
            Agitator := (Level >= LIQ_MIN);
            DrainValve := FALSE;
            IF Temp >= TEMP_SET THEN State := 3; END_IF;
        3: (* React *)
            FillValve := FALSE;
            Heater := (Level >= LIQ_MIN);
            Agitator := (Level >= LIQ_MIN);
            DrainValve := FALSE;
            IF ReactTimer.Q THEN State := 4; END_IF;
        4: (* Drain *)
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := (Level > LVL_LOW);
            IF Level <= LVL_LOW THEN State := 0; END_IF;
    ELSE
        State := 0;
    END_CASE;
END_IF;
END_PROGRAM

PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR
    Count : INT;
    PrevEntry : BOOL;
    PrevExit : BOOL;
END_VAR

IF EntrySensor AND NOT PrevEntry THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
END_IF;
IF ExitSensor AND NOT PrevExit THEN
    IF Count > 0 THEN
        Count := Count - 1;
    END_IF;
END_IF;
PrevEntry := EntrySensor;
PrevExit := ExitSensor;
FullSign := (Count = 3);
EntryBarrierOpen := EntryReq AND (Count < 3);
END_PROGRAM

PROGRAM motor_delay
VAR_INPUT
  StartCmd : BOOL;
  EStop : BOOL;
END_VAR
VAR_OUTPUT
  Motor : BOOL;
END_VAR
VAR
  tStart : TON;
END_VAR
tStart(IN := StartCmd AND EStop, PT := T#3s);
Motor := tStart.Q;
END_PROGRAM

PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR
VAR
    State : INT;
    StarTimer : TON;
END_VAR
IF StopPB OR NOT EStop THEN
    State := 0;
ELSIF State = 0 AND StartPB THEN
    State := 1;
END_IF;
CASE State OF
    0:
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
        StarTimer(IN := FALSE, PT := T#3s);
    1:
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        StarTimer(IN := TRUE, PT := T#3s);
        IF StarTimer.Q THEN
            State := 2;
        END_IF;
    2:
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        StarTimer(IN := FALSE, PT := T#3s);
END_CASE;
END_PROGRAM

PROGRAM ped_crossing
VAR_INPUT
    PedReq : BOOL;
END_VAR
VAR_OUTPUT
    CarGreen : BOOL;
    CarYellow : BOOL;
    CarRed : BOOL;
    PedWalk : BOOL;
END_VAR
VAR
    State : INT := 0;
    tGreen : TON;
    tYellow : TON;
    tWalk : TON;
END_VAR
tGreen(IN := (State = 0), PT := T#3s);
tYellow(IN := (State = 1), PT := T#2s);
tWalk(IN := (State = 2), PT := T#3s);
CASE State OF
0:
    CarGreen := TRUE;
    CarYellow := FALSE;
    CarRed := FALSE;
    PedWalk := FALSE;
    IF tGreen.Q AND PedReq THEN
        State := 1;
    END_IF;
1:
    CarGreen := FALSE;
    CarYellow := TRUE;
    CarRed := FALSE;
    PedWalk := FALSE;
    IF tYellow.Q THEN
        State := 2;
    END_IF;
2:
    CarGreen := FALSE;
    CarYellow := FALSE;
    CarRed := TRUE;
    PedWalk := TRUE;
    IF tWalk.Q THEN
        State := 0;
    END_IF;
END_CASE;
END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
Level : INT;
StartCycle : BOOL;
EStop : BOOL;
END_VAR
VAR_OUTPUT
Pump : BOOL;
Valve : BOOL;
END_VAR
VAR
State : INT;
END_VAR
IF NOT EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
ELSIF State = 0 THEN
    Pump := FALSE;
    Valve := FALSE;
    IF StartCycle AND Level < 90 THEN
        State := 1;
    END_IF
ELSIF State = 1 THEN
    IF Level >= 90 THEN
        State := 2;
        Pump := FALSE;
        Valve := TRUE;
    ELSE
        Pump := TRUE;
        Valve := FALSE;
    END_IF
ELSIF State = 2 THEN
    IF Level <= 10 THEN
        State := 0;
        Pump := FALSE;
        Valve := FALSE;
    ELSE
        Pump := FALSE;
        Valve := TRUE;
    END_IF
ELSE
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF
END_PROGRAM

PROGRAM conveyor_seq
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR
    State : INT;
    SeqTimer : TON;
END_VAR
IF NOT EStop OR StopPB THEN
    State := 0;
    SeqTimer(IN := FALSE);
ELSIF State = 0 THEN
    IF StartPB THEN
        State := 1;
    END_IF;
ELSIF State = 1 THEN
    SeqTimer(IN := TRUE, PT := T#2s);
    IF SeqTimer.Q THEN
        State := 2;
        SeqTimer(IN := FALSE);
    END_IF;
END_IF;
IF State = 0 THEN
    C1 := FALSE;
    C2 := FALSE;
ELSIF State = 1 THEN
    C1 := FALSE;
    C2 := TRUE;
ELSIF State = 2 THEN
    C1 := TRUE;
    C2 := TRUE;
ELSE
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
END_IF;
END_PROGRAM

PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgnTimer : TON;
END_VAR
Healthy := EStop AND NOT StopPB;
PurgeTimer(IN := (State = 1), PT := T#3s);
IgnTimer(IN := (State = 2), PT := T#2s);
IF NOT Healthy THEN
    State := 0;
ELSIF StopPB THEN
    State := 0;
ELSE
    CASE State OF
        0: IF StartPB THEN State := 1; END_IF;
        1: IF PurgeTimer.Q THEN State := 2; END_IF;
        2: IF IgnTimer.Q THEN
               IF Flame THEN State := 3; ELSE State := 0; END_IF;
           END_IF;
        3: IF NOT Flame THEN State := 0; END_IF;
    END_CASE;
END_IF;
IF State = 0 THEN
    Fan := FALSE; Fuel := FALSE; Ignition := FALSE;
ELSIF State = 1 THEN
    Fan := TRUE; Fuel := FALSE; Ignition := FALSE;
ELSIF State = 2 THEN
    Fan := TRUE; Fuel := TRUE; Ignition := TRUE;
ELSIF State = 3 THEN
    Fan := TRUE; Fuel := TRUE; Ignition := FALSE;
END_IF;
END_PROGRAM

PROGRAM two_hand
VAR_INPUT
LH : BOOL;
RH : BOOL;
END_VAR
VAR_OUTPUT
Actuator : BOOL;
END_VAR
VAR
Armed : BOOL;
END_VAR
IF NOT LH AND NOT RH THEN
Armed := TRUE;
ELSIF (LH AND NOT RH) OR (NOT LH AND RH) THEN
Armed := FALSE;
END_IF;
Actuator := Armed AND LH AND RH;
END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
END_VAR

IF NOT Demand AND PrevDemand THEN
    Lead := 1 - Lead;
END_IF;
PrevDemand := Demand;

Pump1 := Demand AND EStop AND (Lead = 0);
Pump2 := Demand AND EStop AND (Lead = 1);
END_PROGRAM

PROGRAM gate
VAR_INPUT
  OpenCmd : BOOL;
  CloseCmd : BOOL;
  OpenLimit : BOOL;
  CloseLimit : BOOL;
  Obstruction : BOOL;
END_VAR
VAR_OUTPUT
  MotorOpen : BOOL;
  MotorClose : BOOL;
END_VAR
VAR
  State : INT;
END_VAR
CASE State OF
  0:
    IF OpenCmd AND NOT OpenLimit THEN
      State := 1;
    ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
      State := 2;
    END_IF;
  1:
    IF OpenLimit THEN
      State := 0;
    END_IF;
  2:
    IF CloseLimit OR Obstruction THEN
      State := 0;
    END_IF;
END_CASE;
MotorOpen := (State = 1) AND NOT OpenLimit;
MotorClose := (State = 2) AND NOT CloseLimit AND NOT Obstruction;
END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T1 : TON;
    T2 : TON;
END_VAR
IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB AND State = 0 THEN
    State := 1;
END_IF;
T1(IN := State = 1, PT := T#2s);
T2(IN := State = 2, PT := T#2s);
IF T1.Q AND State = 1 THEN
    State := 2;
END_IF;
IF T2.Q AND State = 2 THEN
    State := 3;
END_IF;
C3 := State >= 1;
C2 := State >= 2;
C1 := State = 3;
END_PROGRAM

PROGRAM dosing
VAR_INPUT
  Trigger : BOOL;
  Reset : BOOL;
END_VAR
VAR_OUTPUT
  Done : BOOL;
END_VAR
VAR
  Count : INT;
  PrevTrigger : BOOL;
END_VAR

IF Reset THEN
  Count := 0;
  Done := FALSE;
ELSIF Trigger AND NOT PrevTrigger THEN
  IF Count < 3 THEN
    Count := Count + 1;
  END_IF;
END_IF;
Done := (Count = 3);
PrevTrigger := Trigger;
END_PROGRAM
